<?php
namespace App\Controllers;
use PDO;use App\Core\{Auth,Response,View};
final class ReceivedInvoicesController{public function __construct(private PDO $db){}public function index():void{Auth::requirePermission('expenses');$s=$this->db->prepare('SELECT * FROM received_invoices WHERE workspace_id=? ORDER BY due_date IS NULL,due_date DESC,id DESC');$s->execute([Auth::workspaceId()]);View::render('received/index',['title'=>'Přijaté faktury','rows'=>$s->fetchAll()]);}public function save():void{Auth::requirePermission('expenses');Auth::verifyCsrf();$d=$_POST;$this->db->prepare('INSERT INTO received_invoices(workspace_id,supplier,ico,dic,document_number,variable_symbol,issue_date,due_date,currency,cnb_rate,amount_without_vat,vat_amount,total_amount,payment_status,note) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([Auth::workspaceId(),trim($d['supplier']??''),trim($d['ico']??''),trim($d['dic']??''),trim($d['document_number']??''),trim($d['variable_symbol']??''),$d['issue_date']??null,$d['due_date']??null,strtoupper($d['currency']??'CZK'),(float)($d['cnb_rate']??1),(float)($d['amount_without_vat']??0),(float)($d['vat_amount']??0),(float)($d['total_amount']??0),$d['payment_status']??'unpaid',trim($d['note']??'')]);Response::redirect('/received-invoices');}}
